// Regression test for: ZIP code input has no accessible label
// Generated by WebProbe gen-tests from 2026-11-11T19-26-42-760Z, report #8.
// It failed with the bug and passed on the clean site. Edit freely; promote-tests won't overwrite it.

import { test, expect } from "@playwright/test";

test("ZIP code field on checkout has an accessible name 'ZIP code'", async ({ page }) => {
  const pageErrors: Error[] = [];
  page.on("pageerror", (err) => pageErrors.push(err));

  // Checkout is reached with items in the cart, so add one first.
  await page.goto("/");
  await page.getByRole("button", { name: "Add to cart" }).first().click();

  await page.goto("/checkout");
  await expect(page.getByRole("heading", { name: "Checkout", level: 1 })).toBeVisible();

  const zip = page.getByRole("textbox", { name: "ZIP code", exact: true });
  await expect(zip).toBeVisible();

  expect(pageErrors).toEqual([]);
});
